recovered.reconstruction["native_invisible_callbacks"]=[=[-- deobsefactor by zyrixen
-- PARTIAL: reconstructed native maintenance callbacks, not a complete invisible toggle.
-- Original source constructors: 11520 (render), 3813 (physics).
local function readCell(cell)
    return cell[6][cell[5]]
end
local function writeCell(cell, value)
    cell[6][cell[5]] = value
end

local function createInvisibleRenderStep(localPlayer, state, frameCounter, partsCell)
    return function(_deltaTime)
        local character = localPlayer.Character
        if not character or not state.phantomModel or not state.phantomModel.Parent then
            return
        end
        local realRoot = character:FindFirstChild("HumanoidRootPart")
        local phantomRoot = state.phantomModel:FindFirstChild("HumanoidRootPart")
        if realRoot and phantomRoot then
            local realFloorOffset = state.getFloorOffset(character)
            local phantomFloorOffset = state.getFloorOffset(state.phantomModel)
            local height = realRoot.Position.Y - realFloorOffset
            phantomRoot.CFrame = CFrame.new(
                realRoot.Position.X, height + phantomFloorOffset, realRoot.Position.Z
            ) * (realRoot.CFrame - realRoot.CFrame.Position)
            if not phantomRoot.Anchored then
                phantomRoot.Anchored = true
            end
        end

        writeCell(frameCounter, readCell(frameCounter) + 1)
        if readCell(frameCounter) % 2 == 0 then
            for i = 1, #state.motorMap do
                local pair = state.motorMap[i]
                local realMotor, phantomMotor = pair.real, pair.phantom
                if realMotor and phantomMotor and realMotor.Parent and phantomMotor.Parent then
                    phantomMotor.Transform = realMotor.Transform
                end
            end
        end

        local camera = workspace.CurrentCamera
        if not camera then
            return
        end
        local head = character:FindFirstChild("Head")
        if not head then
            return
        end
        local transparency = (camera.CFrame.Position - head.Position).Magnitude < 1 and 1 or 0
        for i = 1, #readCell(partsCell) do
            local part = readCell(partsCell)[i]
            if part.LocalTransparencyModifier ~= transparency then
                part.LocalTransparencyModifier = transparency
            end
        end
    end
end

local function createInvisiblePhysicsStep(state, elapsedCell, partsCell)
    return function(_currentTime, deltaTime)
        if not state.phantomModel or not state.phantomModel.Parent then
            return
        end
        writeCell(elapsedCell, readCell(elapsedCell) + deltaTime)
        if readCell(elapsedCell) < 0.1 then
            return
        end
        writeCell(elapsedCell, 0)
        for i = 1, #readCell(partsCell) do
            local part = readCell(partsCell)[i]
            if part.CanCollide then
                part.CanCollide = false
            end
            if not part.Massless then
                part.Massless = true
            end
            if part.CanTouch then
                part.CanTouch = false
            end
            if part.Name == "HumanoidRootPart" and not part.Anchored then
                part.Anchored = true
            end
        end
    end
end
local function createInvisibleFireHook(remoteCell, settings, rewriteArguments)
    return function(...)
        local receiver = ...
        if not rawequal(receiver, readCell(remoteCell)) then
            return settings.Invisible.OriginalFire(...)
        end
        if settings.Invisible.NamecallHook and not checkcaller() then
            return settings.Invisible.OriginalFire(...)
        end
        local arguments = table.pack(...)
        if settings.Invisible.Enabled then
            return settings.Invisible.OriginalFire(receiver, rewriteArguments(arguments, 2))
        end
        return settings.Invisible.OriginalFire(table.unpack(arguments, 1, arguments.n))
    end
end

return {
    status = "PARTIAL",
    ready_for_delta = false,
    createFireHook = createInvisibleFireHook,
    createRenderStep = createInvisibleRenderStep,
    createPhysicsStep = createInvisiblePhysicsStep,
}
]=]
