recovered.reconstruction["motor_map_matched_offline"]=[=[-- deobsefactor by zyrixen
-- Fallens: isolated motorMap reconstruction from observed VM property accesses.
-- Status: PARTIAL / reconstructed matching logic; native equivalence not yet proven.

local function jointKey(motor)
    if not motor or not motor:IsA("Motor6D") then
        return nil
    end

    local part0, part1 = motor.Part0, motor.Part1
    if not part0 or not part1 then
        return nil
    end

    -- Two different Motor6Ds can have the same Name; include both attachments.
    return motor.Name .. "\0" .. part0.Name .. "\0" .. part1.Name
end

local function indexMotors(model)
    local index = {}
    local unmatched = 0
    for _, desc in ipairs(model:GetDescendants()) do
        if desc:IsA("Motor6D") then
            local key = jointKey(desc)
            if key then
                local candidates = index[key]
                if not candidates then
                    candidates = {}
                    index[key] = candidates
                end
                candidates[#candidates + 1] = desc
            else
                unmatched += 1
            end
        end
    end
    return index, unmatched
end

local function buildMotorMap(character, phantomModel)
    assert(character and phantomModel, "Both character and phantom are required")
    local reference, skippedPhantom = indexMotors(phantomModel)
    local mapped, unmatchedReal = {}, 0

    for _, real in ipairs(character:GetDescendants()) do
        if real:IsA("Motor6D") then
            local key = jointKey(real)
            local matching = key and reference[key]
            if matching and #matching > 0 then
                mapped[#mapped + 1] = { real = real, phantom = table.remove(matching, 1) }
            else
                unmatchedReal += 1
            end
        end
    end

    local excessPhantom = skippedPhantom
    for _, remaining in pairs(reference) do
        excessPhantom += #remaining
    end
    return mapped, { unmatchedReal = unmatchedReal, unmatchedPhantom = excessPhantom }
end

return buildMotorMap
]=]

